CREATE OR REPLACE FUNCTION public.get_world_tax_policies(_world_id uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE rates jsonb; w worlds%ROWTYPE; i integer; npc_rate numeric; BEGIN IF auth.uid() IS NULL OR NOT is_world_member(auth.uid(),_world_id) THEN RAISE EXCEPTION 'Not a world member'; END IF; SELECT * INTO w FROM worlds WHERE id=_world_id; SELECT COALESCE(jsonb_object_agg(user_id::text,LEAST(100,GREATEST(0,COALESCE((player_data->'sovereignty'->>'taxRate')::numeric,0)))),'{}'::jsonb) INTO rates FROM world_members WHERE world_id=_world_id AND player_data->'sovereignty'->>'name' IS NOT NULL; npc_rate := CASE w.npc_aggression WHEN 'high' THEN 35 WHEN 'medium' THEN 20 ELSE 10 END; IF w.enable_npcs THEN FOR i IN 0..w.npc_count-1 LOOP rates:=jsonb_set(rates,ARRAY['npc-'||i],to_jsonb(npc_rate)); END LOOP; END IF; RETURN rates; END $$;
REVOKE EXECUTE ON FUNCTION public.get_world_tax_policies(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.get_world_tax_policies(uuid) TO authenticated,service_role;
COMMENT ON COLUMN public.worlds.npc_tax_rates IS 'DEPRECATED: NPC tax rates now derive from npc_aggression (low=10, medium=20, high=35)';